import { createEffect, createSignal, For, ParentComponent, Show } from "solid-js";

import { Divider } from "#core/ui-next/components/divider.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { VictoryCountdownPlayer } from "#base/ui-next/screens/victories/victory-countdown-bar.jsx";

interface VictoryCountdownTooltipProps {
	players: VictoryCountdownPlayer[];
	countdownDuration: number;
}
const VictoryCountdownTooltipComponent: ParentComponent<VictoryCountdownTooltipProps> = (props) => {
	const [damagedLaunchpads, setDamagedLaunchpads] = createSignal<Record<string, boolean>>({});
	const [countdownRemaining, setCountdownRemaining] = createSignal(0);

	createEffect(() => {
		if (props.players.length > 0) {
			setCountdownRemaining(props.countdownDuration - props.players[0].countdownProgress);
		}
		const result: Record<string, boolean> = {};
		props.players.forEach((victoryCountdownPlayer) => {
			const player = Players.get(victoryCountdownPlayer.playerInfo.playerId);
			if (!player) {
				return;
			}
			result[player.leaderName] = victoryCountdownPlayer.launchpadDamaged;
		});
		setDamagedLaunchpads(result);
	});
	return (
		<Tooltip>
			<Tooltip.Trigger class="pointer-events-none">{props.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame>
					<div class="flex flex-col">
						<div class="font-title text-secondary">
							<L10n.Compose
								text="LOC_VICTORY_PROGRESS_TURNS_REMAINING"
								args={[countdownRemaining()]}
							/>
						</div>
						<Divider.Horizontal margin={2} />
						<For each={Object.entries(damagedLaunchpads())}>
							{([leaderName, launchpadDamaged]) => (
								<Show
									when={launchpadDamaged}
									fallback={<L10n.Compose text={leaderName} />}
								>
									<L10n.Compose
										text="LOC_VICTORIES_SCIENTIFIC_LEADER_DAMAGED_LAUNCHPAD"
										args={[Locale.compose(leaderName)]}
									/>
								</Show>
							)}
						</For>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const VictoryCountdownTooltip = ComponentRegistry.register({
	name: "VictoryCountdownTooltip",
	createInstance: VictoryCountdownTooltipComponent,
});
